(async () => {
  console.log("Stone macro 启动 mode:", args[0]);
  const mode = args[0];
  const last = args.at(-1);
  const actor = canvas.tokens.get(last.tokenId)?.actor;
  if (!actor) return console.warn("找不到 actor");
  const origin = last.origin;
  const active = await fromUuid(origin);
  const caster = active?.parent;
  const dc = caster?.getRollData()?.attributes?.spelldc;
  if (!active || !caster || typeof dc !== "number") return console.warn("Source 或 DC 有误");

  if (mode === "on") {
    console.log("注册 updateCombat 钩子 for", actor.name);
    const hookId = Hooks.on("updateCombat", async combat => {
      const turn = combat.turns?.[combat.turn];
      if (!turn?.actor || turn.actor.id !== actor.id) return;
      const hasFlesh = actor.effects.some(e => e.label === "indigo");
      if (!hasFlesh) return console.log("未持有 Flesh to Stone 效果");

      let succ = actor.flags.world?.success ?? 0;
      let fail = actor.flags.world?.failure ?? 0;

      const roll = await actor.rollAbilitySave("con", { flavor: `Stone Save DC ${dc}` });
      const total = roll.total;
      total >= dc ? succ++ : (fail++, !actor.effects.some(e=>e.label==="Restrained") &&
        await actor.createEmbeddedDocuments("ActiveEffect", [{
          label:"Restrained", icon:"icons/svg/locked.svg",
          changes:[{key:"macro.StatusEffect", mode:0, value:""}],
          duration:{turns:1}
        }]));

      await actor.setFlag("world","success", succ);
      await actor.setFlag("world","failure", fail);

      const chatHtml = `<div class="dnd5e chat-card">
        <header class="card-header"><h3>Flesh to Stone 豁免</h3></header>
        <div class="card-content">
          <p><strong>${actor.name}</strong> 掷骰：<strong>${total}</strong>（DC ${dc}）</p>
          <p>累计 成功：<strong>${succ}</strong>，失败：<strong>${fail}</strong></p>
        </div></div>`;
      ChatMessage.create({content: chatHtml, speaker: ChatMessage.getSpeaker({actor})});

      if (succ >= 3) {
        console.log("三次成功，删除原始 Flesh 效果，解绑 hook", hookId);
        const orig = actor.effects.find(e => e.origin === origin);
        if (orig) await actor.deleteEmbeddedDocuments("ActiveEffect",[orig.id]);
        Hooks.off("updateCombat", hookId);
      } else if (fail >= 3) {
        console.log("三次失败，添加 Petrified，解除 restrain，解绑 hook", hookId);
        if (!actor.effects.some(e=>e.label==="Petrified")) {
          await actor.createEmbeddedDocuments("ActiveEffect",[{
            label:"Petrified", icon:"icons/svg/petrified.svg",
            changes:[{key:"macro.StatusEffect", mode:0, value:"petrified"}],
            duration:{}
          }]);
        }
        const res = actor.effects.filter(e=>e.label==="Restrained");
        if (res.length) await actor.deleteEmbeddedDocuments("ActiveEffect",res.map(e=>e.id));
        Hooks.off("updateCombat", hookId);
      }
    });
    console.log("hook 注册完成, id:", hookId);
  }

  if (mode === "off") {
    console.log("mode off：清理 flags、Restrained、Petrified，并解绑 hook");
    const orig = actor.effects.find(e => e.origin === origin);
    if (orig) await actor.deleteEmbeddedDocuments("ActiveEffect",[orig.id]);
    const pe = actor.effects.filter(e => e.label === "Petrified");
    if (pe.length) await actor.deleteEmbeddedDocuments("ActiveEffect",pe.map(e=>e.id));
    const re = actor.effects.filter(e => e.label === "Restrained");
    if (re.length) await actor.deleteEmbeddedDocuments("ActiveEffect",re.map(e=>e.id));
    await actor.unsetFlag("world","success");
    await actor.unsetFlag("world","failure");
    // 主动删除效果时也要解绑 hook
    Hooks.off("updateCombat");
  }
})();
